package org.mcrf.client

import android.widget.LinearLayout

class CoreTuningUi(private val activity: MainActivity) {
    companion object { const val PAGE_TITLE = "Основное ядро · расширенные параметры" }
    fun pageView(): LinearLayout = view()
    fun advancedView(): LinearLayout = view()
    fun view(): LinearLayout {
        val store = CoreTuningStore(activity)
        val form = CoreTuningForm(activity,store.load().json()) { store.save(CoreTuningSettings.fromJson(it)) }
            .grouped(CoreTuningSettings().json()){store.load().json()}
        form.section("Проверка защищённых соединений")
        form.field("certificateStore","Набор доверенных сертификатов","system — системное хранилище; mozilla — набор Mozilla в ядре. Обычно оставьте system. Меняйте только при известной проблеме доверия сертификатам.")
        form.toggle("insecure","Пропускать проверку TLS сертификатов","Отключает проверку сертификата для TLS выходов. По умолчанию выключено; снижает защиту соединения.")
        form.section("Объединение потоков · Multiplex")
        form.toggle("muxDefault","Объединять потоки по умолчанию","Для VMess/VLESS/Trojan/Shadowsocks, когда профиль не определяет значение. Vision не включается автоматически.")
        form.field("muxProtocol","Способ объединения потоков","smux, yamux или h2mux. Должен поддерживаться сервером; случайная смена может нарушить подключение.")
        form.field("muxConcurrency","Потоков на соединение","От 1 до 1024. Явные значения профиля сохраняются.",true)
        form.toggle("muxPadding","Дополнять объединённые потоки данными","Padding затрудняет определение размеров передач, но увеличивает расход трафика. Применяется, только если профиль не задал своё значение.")
        form.section("Маскировка TLS")
        form.toggle("fragmentDefault","Разбивать начало TLS-соединения на части","Может помочь при отдельных сетевых ограничениях, но не ускоряет соединение. Используется встроенный tls.fragment; явный выбор профиля важнее.")
        form.field("fragmentDelay","Пауза встроенного фрагментирования","Длительность с единицей: например 500ms — полсекунды. Отдельный TLS-модуль настраивается отдельно.")
        form.field("fingerprint","Маскировка TLS под браузер · uTLS","Меняет вид начала TLS-соединения. Значения, например chrome, firefox, safari, android. Пусто — не менять; явные параметры профиля сохраняются.")
        form.section("Тонкая настройка HTTP/2 и QUIC")
        form.hint("Меняйте только для решения конкретной проблемы сети. Неудачные значения могут снизить скорость. Параметры применяются лишь к совместимым протоколам, а не ко всем серверам.")
        form.field("idleTimeout","Закрывать простаивающее соединение через","Время без передачи данных, после которого соединение закрывается. Например 30s — 30 секунд. Пусто — значение ядра.")
        form.field("keepAlive","Как часто поддерживать соединение","Интервал служебных пакетов, чтобы сеть не закрывала простаивающее соединение. Например 15s. Частые пакеты расходуют трафик и батарею; пусто — значение ядра.")
        form.field("streamWindow","Данных без подтверждения на один поток · байты","Лимит данных в пути для одной передачи. Большее значение иногда помогает на быстрой сети с большой задержкой, но требует больше памяти. Пусто — автоматически; от 1 до 2147483647.")
        form.field("connectionWindow","Данных без подтверждения на соединение · байты","Общий лимит данных в пути для потоков одного соединения. Не лимит расхода трафика. Пусто — автоматически; от 1 до 2147483647. Явные параметры сервера сохраняют приоритет.")
        form.field("maxStreams","Одновременных потоков HTTP/2 / QUIC","Сколько передач разрешено вести одновременно внутри соединения. Больше не всегда быстрее. 0 — автоматически; иначе от 1 до 1000000.",true)
        form.field("initialPacketSize","Начальный размер пакета QUIC · байты","С какой порции данных начинать передачу. Слишком большой пакет может не проходить через сеть. 0 — автоматически; иначе от 1200 до 65527. Обычно оставьте 0.",true)
        form.toggle("disablePmtu","Отключить подбор размера пакета QUIC","PMTU подбирает размер пакета под сеть. Оставьте выключенным. Включать стоит только как обход подтверждённой проблемы: отключение может ухудшить связь. Для совместимых Hysteria/Hysteria2/TUIC и HTTP/3.")
        form.finishGroups()
        return form.view
    }
}
